<template>
  <div ref="containerRef" class="three-container">
    <VirtualJoystick
      ref="virtualJoystickRef"
      :is-orbit-control-active="uiState.isOrbitControlActive"
      :is-orbit-control-manually-activated="uiState.isOrbitControlManuallyActivated"
      @joystick-move="onJoystickMove"
      @run-toggle="onRunToggle"
      @touch-delta="onTouchDelta"
      @camera-rotate="onCameraRotate"
      @camera-rotation-speed="onCameraRotationSpeed"
      @operation-mode-change="onOperationModeChange"
    />

    <!-- 跳跃按钮 (独立) -->
    <div class="jump-button-container">
      <div
        class="jump-button center-button"
        :class="{ active: uiState.isJumping }"
        @touchstart.prevent.stop="onJumpStart"
        @touchend.prevent.stop="onJumpEnd"
        @mousedown.prevent.stop="onJumpStart"
        @mouseup.prevent.stop="onJumpEnd"
        @click.prevent.stop
      >
        <svg viewBox="0 0 48 48" fill="currentColor">
          <!-- 跳跃小人图标 - 更动感的设计 -->
          <!-- 头部 -->
          <circle cx="24" cy="10" r="5" />
          <!-- 身体 (稍微倾斜) -->
          <ellipse cx="24" cy="20" rx="3" ry="8" transform="rotate(5 24 20)" />
          <!-- 左臂 (大幅向上摆动) -->
          <ellipse cx="18" cy="16" rx="1.5" ry="6" transform="rotate(-45 18 16)" />
          <!-- 右臂 (向后摆动) -->
          <ellipse cx="30" cy="18" rx="1.5" ry="6" transform="rotate(25 30 18)" />
          <!-- 左腿 (向前踢) -->
          <ellipse cx="21" cy="30" rx="2" ry="8" transform="rotate(-25 21 30)" />
          <!-- 右腿 (向后蹬) -->
          <ellipse cx="27" cy="32" rx="2" ry="8" transform="rotate(35 27 32)" />

          <!-- 跳跃轨迹弧线 -->
          <path
            d="M8 38 Q24 28 40 38"
            stroke="currentColor"
            stroke-width="2.5"
            fill="none"
            opacity="0.7"
            stroke-dasharray="3,2"
          />

          <!-- 地面冲击波 -->
          <ellipse cx="24" cy="42" rx="12" ry="2" opacity="0.4" />
          <ellipse cx="24" cy="43" rx="8" ry="1" opacity="0.3" />
        </svg>
      </div>
    </div>

    <!-- 右侧竖向按钮组 -->
    <div class="vertical-button-group">
      <!-- 环绕按钮 -->
      <div
        class="orbit-button vertical-button"
        @touchstart.prevent.stop="onOrbitButtonStart"
        @touchend.prevent.stop="onOrbitButtonEnd"
        @mousedown.prevent.stop="onOrbitButtonStart"
        @mouseup.prevent.stop="onOrbitButtonEnd"
        @click.prevent.stop
      >
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <circle cx="12" cy="12" r="8" />
          <circle cx="12" cy="12" r="3" fill="currentColor" />
        </svg>
      </div>

      <!-- 全屏按钮 -->
      <div
        class="fullscreen-toggle vertical-button"
        :class="{ active: uiState.isFullscreen }"
        @click.prevent.stop="toggleFullscreen"
        @touchstart.prevent.stop
        @touchend.prevent.stop="toggleFullscreen"
        @mousedown.prevent.stop
        @mouseup.prevent.stop
      >
        <svg v-if="uiState.isFullscreen" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M8 3v3a2 2 0 0 1-2 2H3m18 0h-3a2 2 0 0 1-2-2V3m0 18v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3"></path>
        </svg>
        <svg v-else viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3"></path>
        </svg>
      </div>
    </div>

    <!-- v20260807（Breaking · UIModule 收编 toast）：Vue toast div 已删除 ——
         toast 由 uiModule CSS2D overlay 直挂 DOM，Vue 不再需要监听 uiState.showToast/toastMessage。
         SDK.showToast(message, duration) API 保持不变。 -->

    <!-- 当前所在模块信息浮层 -->
    <Transition name="module-info">
      <div v-if="currentModuleInfo" class="module-location-panel">
        <!-- 顶部：模块名 + 状态徽章 -->
        <div class="module-location-header">
          <div
            class="module-location-status-dot"
            :class="{
              loading: moduleLoading,
              loaded: !moduleLoading && currentModuleInfo.isLoaded,
              unloaded: !moduleLoading && !currentModuleInfo.isLoaded,
            }"
          ></div>
          <div class="module-location-name" :style="{ color: currentModuleInfo.color }">
            {{ currentModuleInfo.moduleName }}
          </div>
        </div>

        <!-- 状态文字 -->
        <div class="module-location-status">
          <span v-if="moduleLoading">地块加载中…</span>
          <span v-else-if="currentModuleInfo.isLoaded">当前地块已加载</span>
          <span v-else>当前地块未加载</span>
        </div>

        <!-- 操作按钮 / 加载占位 -->
        <button
          v-show="!moduleLoading"
          class="module-location-btn"
          :class="{ loaded: currentModuleInfo.isLoaded }"
          @click.stop="onModuleLocationAction"
          @touchstart.prevent.stop
          @touchend.prevent.stop="onModuleLocationAction"
        >
          <span v-if="currentModuleInfo.isLoaded">点击卸载</span>
          <span v-else>点击加载</span>
        </button>
        <div v-show="moduleLoading" class="module-location-btn-placeholder">
          <span class="module-location-spinner"></span>
        </div>

        <!-- 碰撞体可视化勾选项（与 Debug Panel 状态联动） -->
        <div
          class="module-location-checkboxes"
          :class="{ highlighted: showFirstLoadModal }"
        >
          <div class="module-location-checkboxes-title">碰撞体可视化</div>
          <div class="module-location-checkboxes-row">
            <label class="module-location-checkbox" @click.stop>
              <input
                type="checkbox"
                :checked="floatingDebugConfig.showColliders"
                @change="onFloatingColliderToggle('showColliders', ($event.target as HTMLInputElement).checked)"
              />
              <span>线框</span>
            </label>
            <label class="module-location-checkbox" @click.stop>
              <input
                type="checkbox"
                :checked="floatingDebugConfig.showColliderSolid"
                @change="onFloatingColliderToggle('showColliderSolid', ($event.target as HTMLInputElement).checked)"
              />
              <span>面</span>
            </label>
          </div>
        </div>
      </div>
    </Transition>

    <!-- 首次加载提示：聚焦"当前所在模块信息浮层"的"碰撞体可视化"区域 -->
    <Transition name="first-load-hint">
      <div
        v-if="showFirstLoadModal"
        class="first-load-hint-mask"
        @click.self="closeFirstLoadModal"
      >
        <div class="first-load-hint-bubble" @click.stop>
          <div class="first-load-hint-arrow"></div>
          <div class="first-load-hint-title">
            <span class="first-load-hint-title-icon">💡</span>
            提示
          </div>
          <div class="first-load-hint-content">
            为了让高斯泼溅场景展示完整，已自动隐藏碰撞体线与面。<br />
            如需重新开启，可点击左侧高亮的 <b>「碰撞体可视化」</b> 选项，或在 <b>「Debug Panel · 可视化」</b> 中切换。
          </div>
          <button class="first-load-hint-btn" @click.stop="closeFirstLoadModal">我知道了</button>
        </div>
      </div>
    </Transition>

    <!-- Debug面板 -->
    <DebugPanel
      v-if="showDebugViewer"
      :camera-sensitivity="cameraSensitivity"
      :environment-panel-visible="showEnvironmentPanel"
      :scene-panel-visible="showScenePanel"
      :performance-panel-visible="showPerformancePanel"
      @log-debug-info="onLogDebugInfo"
      @log-rebase-info="onLogRebaseInfo"
      @toggle-environment-panel="showEnvironmentPanel = !showEnvironmentPanel"
      @toggle-scene-panel="showScenePanel = !showScenePanel"
      @toggle-performance-panel="showPerformancePanel = !showPerformancePanel"
    />

    <!-- 子面板停靠区：按打开顺序横向排列，关闭后由 flex 自动向左补位。 -->
    <div v-if="showDebugViewer" class="side-panel-dock">
      <EnvironmentPanel
        :style="{ order: panelOrder.indexOf('environment') }"
        :visible="showEnvironmentPanel"
        @close="showEnvironmentPanel = false"
      />
      <ScenePanel
        ref="scenePanelRef"
        :style="{ order: panelOrder.indexOf('scene') }"
        :visible="showScenePanel"
        :initial-config="initialDebugConfig"
        @close="showScenePanel = false"
        @config-change="onDebugConfigChange"
        @module-toggle="onModuleToggle"
        @reset-physics="onResetPhysics"
      />
      <PerformancePanel
        v-if="showPerformancePanel"
        :style="{ order: panelOrder.indexOf('performance') }"
        @close="showPerformancePanel = false"
      />
    </div>

    <!-- 交互对话框 -->
    <InteractionDialog ref="interactionRef" />
  </div>
</template>

<script setup lang="ts">
/**
 * @changelog
 * | 版本   | 变更说明                                                                 | 关联                                                   |
 * | v1.0.0 | 阶段1：接入环境/场景双面板停靠区，按打开顺序横向排列并自动补位。 | REQ: debugpanel-拆分-阶段1 TECH: scene-panel-phase1-framework |
 * | v1.0.1 | EngineContext 改用 shallowRef + markRaw，禁止 Vue 深层代理 Three.js 对象图。 | BUGFIX: depth-debug-predepth-proxy |
 * | v1.1.0 | 接入同级性能统计面板并沿用停靠排序。 | REQ: 20260803-depth-pipeline-phase4 TECH: performance-panel-layout |
 * | v1.2.0 | 性能面板改为条件挂载，避免隐藏组件更新竞争。 | BUGFIX: performance-panel-vue-update |
 * /@changelog
 *
 * @author DannyCheung
 */
import { ref, reactive, onMounted, onUnmounted, computed, watch } from 'vue';
import { useRoute } from 'vue-router';
import VirtualJoystick from '../../components/VirtualJoystick.vue';
import DebugPanel from '../../components/DebugPanel.vue';
import EnvironmentPanel from '../../components/EnvironmentPanel.vue';
import ScenePanel from '../../components/ScenePanel.vue';
import PerformancePanel from '../../components/PerformancePanel.vue';
import InteractionDialog from '../../components/InteractionDialog.vue';
import {
  ViewerSDK,
  DialogType,
  CLIFF_DETECTION_CONFIG,
  lightModule,
  audioModule,
  getModule,
  gs3dModule,
  // Wave-1 (2026-07 pluggable-refactor)：从 sdk 必装链摘除，改由 viewer 入口 extraModules 显式装配
  npcManagerModule,
  npcSystemModule,
  debugModule,
  // thirdroom input 收官（配套 sdk-input-bindings 整体删除）：H5 层自订阅弧线/inputReset
  // v6.0.0：subscribeActionEdge / subscribeInputReset / pushRawInput 改走 inputModule.api.xxx(ctx, ...)
  inputModule,
  // v5.0.0（Breaking · SDK 门面转发壳清理）：消费方切 ctx + ECS helper 直调
  viewportModule,
  // v6.0.0：orbitSetAutoRotate 改走 cameraModule.api.xxx(ctx, ...)
  cameraModule,
  // v6.0.0：setDebugConfig / logDebugInfo / logRebaseInfo 改走 debugModule.api.xxx(ctx, ...)
  // debugModule 已在上方 imports 内，不重复导入
} from '@tencent/viewer-sdk';
import type { ModuleLocationInfo, EngineContext, URLCharacterParams, Gs3dModuleState, RegionModule } from '@tencent/viewer-sdk';
import { provideEngineContext, useEngineContextGetter } from '../../composables/useEngineContext';
import { hasNewRouteParams, buildURLParamsFromRoute, getShowDebugViewerFromRoute, parseURLParamsFromQuery, getExtraParamsFromRoute, parseExtraParamsFromQuery, resolveSceneUrlFromSiteUri } from '../../utils/route-params';


// DOM 引用
const containerRef = ref<HTMLDivElement>();
const virtualJoystickRef = ref<InstanceType<typeof VirtualJoystick>>();
const scenePanelRef = ref<InstanceType<typeof ScenePanel>>();
const interactionRef = ref<DialogType>();

// viewerSDK 实例
const viewerSDK = new ViewerSDK();






// 读取路由参数
const route = useRoute();

// EngineContext 注入：viewerSDK.init() 是异步的，ctx 在 onMounted 末尾才有值；
// 这里在 setup 顶层先 provide 一个 Ref<undefined>，ScenePanel 及其调试/物理/实体子面板
// 通过 useEngineContext / useEngineContextGetter 注入同一个 Ref 引用，ctx 就绪后自动响应。
// 对齐 SceneViewer.vue 的写法。
const engineCtxRef = ref<EngineContext | undefined>(undefined);
provideEngineContext(engineCtxRef);

// thirdroom 路径 3 范式：本组件 onMounted 内是「唯一原始供料点」（L426 engineCtxRef.value = ...），
// 下游消费（onUIStateChange 回调 / onModuleLocationAction / onModuleToggle 等）统一走 getCtx()
// inject 拿最新 ctx，与 sdk 门面完全解耦。对齐 useMainThreadContext 的 useContext(MainThreadUIContext)。
const getCtx = useEngineContextGetter();

// thirdroom input 收官（配套 SDK sdk-input-bindings 删除）：H5 层自订阅句柄集合
const inputUnsubscribes = ref<Array<() => void>>([]);

// v20260807（Breaking · UIModule 收编 toast）：`showToast: boolean` / `toastMessage: string`
// 两字段从 pluginUIState 移除 —— toast 由 uiModule CSS2D overlay 直挂 DOM，Vue 不再感知 toast 状态。
const pluginUIState = ref<{
  isOrbitControlActive: boolean;
  isOrbitControlManuallyActivated: boolean;
  isFullscreen: boolean;
  currentModelId: string;
  selectedModelId: string;
  isJumping: boolean;
  isSceneReady: boolean;
}>({
  isOrbitControlActive: false,
  isOrbitControlManuallyActivated: false,
  isFullscreen: false,
  currentModelId: '',
  selectedModelId: '',
  isJumping: false,
  isSceneReady: false,
});

// 从 viewerSDK 获取的响应式状态
const uiState = computed(() => ({
  ...pluginUIState.value,
}));

// 当前所在模块信息
const currentModuleInfo = ref<ModuleLocationInfo | null>(null);
const moduleLoading = ref(false);

// 用于标记 onModuleToggle 中的加载操作是否已被取消（浮层触发加载时会递增此版本号）
let moduleToggleVersion = 0;

// 初始调试配置（模板和场景就绪后共用，避免硬编码重复）
const initialDebugConfig = { showColliderSolid: true, showGaussianBounds: true };

/**
 * 浮层上的"碰撞体可视化"checkbox 状态。
 * - 与 Debug Panel 上的 showColliders / showColliderSolid 双向联动
 * - 初始值与 initialDebugConfig 保持一致（showColliders 默认 false，showColliderSolid 默认 true）
 * - panel 端勾选变化通过 onDebugConfigChange 回流到这里
 * - 浮层勾选变化通过 onFloatingColliderToggle 推到 viewerSDK 与 panel
 */
const floatingDebugConfig = reactive({
  showColliders: false,
  showColliderSolid: !!initialDebugConfig.showColliderSolid,
});

// 是否已经在本页面显示过"首次加载隐藏碰撞体"的提示弹窗
const hasShownFirstLoadHint = ref(false);
// 控制弹窗显隐
const showFirstLoadModal = ref(false);

// 摄像机灵敏度（用于 DebugPanel）
const pluginCameraSensitivity = ref(0.003);
const cameraSensitivity = computed(() => pluginCameraSensitivity.value);

// 标记 viewerSDK 是否已初始化（用于触发 computed 重新计算）
const isPluginInitialized = ref(false);

// 是否展示调试 UI（新格式：route params/segments | 老格式：URL query 回退）
const showDebugViewer = ref(getShowDebugViewerFromRoute(route));

// 子面板显隐由本页统一维护，DebugPanel 只负责触发切换事件。
const showEnvironmentPanel = ref(false);
const showScenePanel = ref(false);
const showPerformancePanel = ref(false);
type SidePanelKey = 'environment' | 'scene' | 'performance';
const panelOrder = ref<SidePanelKey[]>([]);

function updatePanelOrder(panel: SidePanelKey, visible: boolean) {
  const index = panelOrder.value.indexOf(panel);
  if (visible && index === -1) {
    panelOrder.value.push(panel);
  } else if (!visible && index !== -1) {
    panelOrder.value.splice(index, 1);
  }
}

watch(showEnvironmentPanel, (visible) => updatePanelOrder('environment', visible));
watch(showScenePanel, (visible) => updatePanelOrder('scene', visible));
watch(showPerformancePanel, (visible) => updatePanelOrder('performance', visible));

// v20260728（Breaking · SceneManager 瘦身第十刀）：`viewerSDK.getDebugManager()` public API 已删除。
// v20260813（SDK 门面收敛 · sceneManager prop 死代码整体清理）：SceneManager 类整体废除后
//   `viewerSDK.getSceneManager()` public API 已删除；DebugPanel/EnvironmentPanel/ScenePanel
//   内部 useEngineContextGetter() inject EngineContext + ctx-based helpers，无需父组件转发。
// v20260817（getContext 落地）：DebugSceneViewer 注入源对齐 SceneViewer.vue，切到 viewerSDK.getContext()。
onMounted(async () => {
  if (!containerRef.value) return;

  const urlParams: URLCharacterParams = hasNewRouteParams(route)
    ? buildURLParamsFromRoute(route)
    : parseURLParamsFromQuery();
  const extraParams = hasNewRouteParams(route)
    ? getExtraParamsFromRoute(route)
    : parseExtraParamsFromQuery();
  console.log('路由 params:', urlParams);

  // 如果 sceneUrl 是 siteUri（.site 结尾），从场景配置中解析真实 modelUrl
  if (urlParams.sceneUrl?.endsWith('.site')) {
    urlParams.sceneUrl = await resolveSceneUrlFromSiteUri(urlParams.sceneUrl);
    console.log('siteUri 解析结果:', urlParams.sceneUrl);
  }

  await viewerSDK.init({
    ...extraParams,
    container: containerRef.value,
    sceneUrl: urlParams.sceneUrl,
    thirdPartyUrl: urlParams.thirdPartyUrl,
    defaultOperationMode: 'dual',
    enableCliffDetection: true,
    cliffDetectionMode: 'slide',
    cliffDetectionConfig: {
      enabled: CLIFF_DETECTION_CONFIG.ENABLED,
      checkDistance: CLIFF_DETECTION_CONFIG.CHECK_DISTANCE,
      maxFallDistance: CLIFF_DETECTION_CONFIG.MAX_FALL_DISTANCE,
      safetyMargin: CLIFF_DETECTION_CONFIG.SAFETY_MARGIN,
    },
    interactionRef: interactionRef.value!,
    gaussianAutoLoad: false, // 禁用高斯泼溅自动加载，改为手动点击模块列表加载
    // Wave-1 (2026-07 pluggable-refactor)：SDK v2.2.0 后 npc/debug 从必装链摘除，此处显式补装保持行为等价
    // 注：animationModule 已于 20260714 中央化并重回 SDK 必装链（character/npc 硬依赖），无需在此补装
    extraModules: [lightModule, audioModule, npcManagerModule, npcSystemModule, debugModule],
    hideDebugViewer: !showDebugViewer.value,
  });

  // 监听 viewerSDK 状态变化
  viewerSDK.onUIStateChange((newState) => {
    Object.assign(pluginUIState.value, newState);

    // 场景就绪后，从 sceneManager 中获取模块列表并传给 ScenePanel。
    if (newState.isSceneReady) {
      // v15.1.0：GaussianBoundsDebugHelper 装配宿主下沉 Gs3dSubModule 自建，
      // onModuleLocationChange 直接走 gs3dHandle 注册（替代 getBoundsDebugHelper 二次跳转）。
      // v20260813（thirdroom 路径 3）：下游消费改走 getCtx() inject，与 sdk 门面解耦
      const ctx = getCtx();
      const gs3dHandle = ctx
        ? getModule<Gs3dModuleState>(ctx, gs3dModule).handle
        : null;
      const modules = (gs3dHandle?.getModules() ?? []) as RegionModule[];
      if (modules.length > 0) {
        scenePanelRef.value?.setRegionModules(modules);
      }

      // 场景就绪后，重新应用初始调试配置
      // （初始化阶段场景尚未加载完毕，showColliders / showGaussianBounds 等无法生效）
      {
        const ctx = engineCtxRef.value;
        if (ctx) getModule(ctx, debugModule).api.setDebugConfig(ctx, initialDebugConfig);
      }

      // 注册模块位置变化回调，当人物进入/离开某个模块时更新 UI
      gs3dHandle?.onModuleLocationChange((info) => {
        currentModuleInfo.value = info;
        // 当切换模块时重置加载状态
        moduleLoading.value = false;
      });
    }
  });

  viewerSDK.onCameraSensitivityChange((newValue) => {
    pluginCameraSensitivity.value = newValue;
  });

  // 初始化状态同步
  Object.assign(pluginUIState.value, viewerSDK.uiState);
  pluginCameraSensitivity.value = viewerSDK.cameraSensitivity;

  // 注入 EngineContext：viewerSDK.init() 完成后 ctx 才存在，
  // 此时把 ctx 写入 provide 的 Ref，ScenePanel 子树内的 useEngineContext /
  // useEngineContextGetter 会立即拿到最新值。
  // ⚠️ 必须在 isPluginInitialized 之前：isPluginInitialized 会触发 DebugPanel 的
  // sceneManager watcher + onSceneReady 回调同步执行 init 函数，内部通过 getCtx()
  // 读取 engineCtxRef.value，若尚未赋值则 available 一直为 false 导致 Checkbox 不可见。
  // v20260813：SDK 门面收敛，改走 viewerSDK.getContext() 获取 EngineContext（不再暴露 WebEngine）
  engineCtxRef.value = viewerSDK.getContext() ?? undefined;

  isPluginInitialized.value = true;

  // thirdroom input 收官（配套 SDK sdk-input-bindings.ts 删除）：H5 层自订阅
  // - Character.MoveLeft/MoveRight 沿：驱动 VirtualJoystick 弧线动画
  // - windowBlurred 上升沿：驱动 VirtualJoystick 强制重置
  const ctx = engineCtxRef.value;
  if (ctx) {
    // v6.0.0：subscribeActionEdge / subscribeInputReset 改走 inputModule.api
    const inputApi = getModule(ctx, inputModule).api;
    inputUnsubscribes.value.push(
      inputApi.subscribeActionEdge(ctx, 'Character.MoveLeft', 'pressed', () => {
        virtualJoystickRef.value?.showEdgeArcFromKeyboard('left', false);
      }),
      inputApi.subscribeActionEdge(ctx, 'Character.MoveLeft', 'released', () => {
        virtualJoystickRef.value?.startEdgeArcFadeOut();
      }),
      inputApi.subscribeActionEdge(ctx, 'Character.MoveRight', 'pressed', () => {
        virtualJoystickRef.value?.showEdgeArcFromKeyboard('right', false);
      }),
      inputApi.subscribeActionEdge(ctx, 'Character.MoveRight', 'released', () => {
        virtualJoystickRef.value?.startEdgeArcFadeOut();
      }),
      inputApi.subscribeInputReset(ctx, () => {
        virtualJoystickRef.value?.forceReset();
      }),
    );
  }

  // 开始动画循环
  viewerSDK.animate();
});

onUnmounted(() => {
  // thirdroom input 收官：释放 H5 层自订阅句柄（在 sceneManager.dispose 之前，避免 subscribers 集合已释放二次 delete）
  inputUnsubscribes.value.forEach((unsub) => unsub());
  inputUnsubscribes.value = [];
  // 清理 inject 的 ctx 引用，避免子组件在卸载阶段访问已 dispose 的 EngineContext
  engineCtxRef.value = undefined;
  viewerSDK?.dispose();
});

// 监听路由 params 变化，任何参数改变时触发页面刷新（重新加载场景）
watch(
  () => JSON.stringify(route.params),
  (newVal, oldVal) => {
    if (newVal !== oldVal && oldVal !== undefined) {
      window.location.reload();
    }
  },
);

