// ==================== Debug 事件处理方法 ====================

function onDebugConfigChange(config: any) {
  const ctx = engineCtxRef.value;
  if (ctx) getModule(ctx, debugModule).api.setDebugConfig(ctx, config);

  // 同步 panel 上的"碰撞体线框/面"状态到浮层 checkbox（双向联动的 panel→浮层 方向）
  // 同时保证两者互斥：若两者同时为 true（理论上 panel 侧已互斥，这里做防御），则以本次变更为准、另一项置 false
  if (config && typeof config === 'object') {
    if (typeof config.showColliders === 'boolean') {
      floatingDebugConfig.showColliders = config.showColliders;
    }
    if (typeof config.showColliderSolid === 'boolean') {
      floatingDebugConfig.showColliderSolid = config.showColliderSolid;
    }
    if (floatingDebugConfig.showColliders && floatingDebugConfig.showColliderSolid) {
      // 以本次 payload 中最后出现的那个为准（如果都在 payload 里，优先保留 solid，因为默认初始就是 solid）
      if (typeof config.showColliders === 'boolean' && config.showColliders) {
        floatingDebugConfig.showColliderSolid = false;
      } else {
        floatingDebugConfig.showColliders = false;
      }
    }
  }
}

/**
 * 浮层 checkbox 变更（线框 / 面 互斥，允许同时都不选）：
 * 1. 当前项置为 value；若 value=true，则把另一项强制置 false
 * 2. 将完整的 { showColliders, showColliderSolid } 一次性同步给 viewerSDK，避免两次 update 导致的中间态闪烁
 * 3. 通过 ScenePanel 暴露的 applyDebugConfig 命令式同步调试子面板的 checkbox UI
 *    （注意：applyDebugConfig 不会再 emit configChange，避免回环）
 */
function onFloatingColliderToggle(field: 'showColliders' | 'showColliderSolid', value: boolean) {
  const other: 'showColliders' | 'showColliderSolid' =
    field === 'showColliders' ? 'showColliderSolid' : 'showColliders';

  floatingDebugConfig[field] = value;
  // 互斥：勾选一个时，取消另一个
  if (value) {
    floatingDebugConfig[other] = false;
  }

  const payload = {
    showColliders: floatingDebugConfig.showColliders,
    showColliderSolid: floatingDebugConfig.showColliderSolid,
  };
  // v20260817（SDK v5.0.0 · 转发壳清理）：viewerSDK.updateDebugConfig 已删除，改走 setDebugConfig(ctx, ...)
  // v6.0.0：setDebugConfig 改走 debugModule.api.xxx(ctx, ...)
  const ctx = getCtx();
  if (ctx) getModule(ctx, debugModule).api.setDebugConfig(ctx, payload);
  scenePanelRef.value?.applyDebugConfig?.(payload);
}

