/**
 * 当前所在模块的加载/卸载操作
 * 加载时会先取消左侧面板正在加载的模块，再卸载所有其他已加载的模块，只展示当前要加载的模块
 */
async function onModuleLocationAction() {
  if (!currentModuleInfo.value || moduleLoading.value) return;

  const { moduleName, isLoaded } = currentModuleInfo.value;
  // B8：旧 getGaussianSplattingManager() 删除，改走 ECS getModule 范式拿 gs3d handle
  // v20260813（thirdroom 路径 3）：下游消费改走 getCtx() inject，与 sdk 门面解耦
  const ctx = getCtx();
  const gsManager = ctx
    ? getModule<Gs3dModuleState>(ctx, gs3dModule).handle
    : null;

  if (isLoaded) {
    // 卸载当前模块
    gsManager?.manualUnloadModule(moduleName);
    // 手动刷新当前模块状态
    currentModuleInfo.value = { ...currentModuleInfo.value, isLoaded: false };
    // 同步 ScenePanel 调试子面板中的模块加载状态。
    scenePanelRef.value?.onModuleUnloaded?.(moduleName);
  } else {
    // ==================== 首次加载隐藏碰撞体可视化（仅一次） ====================
    // 浮层上首次点击"点击加载"时，自动取消"显示碰撞体线框/面"，
    // 让高斯泼溅场景视觉更纯净，并弹窗告知用户后续如何重新开启。
    if (!hasShownFirstLoadHint.value) {
      hasShownFirstLoadHint.value = true;

      const needsHide =
        floatingDebugConfig.showColliders || floatingDebugConfig.showColliderSolid;
      if (needsHide) {
        floatingDebugConfig.showColliders = false;
        floatingDebugConfig.showColliderSolid = false;
        const ctx = engineCtxRef.value;
        if (ctx) getModule(ctx, debugModule).api.setDebugConfig(ctx, {
          showColliders: false,
          showColliderSolid: false,
        });
        scenePanelRef.value?.applyDebugConfig?.({
          showColliders: false,
          showColliderSolid: false,
        });
      }
      // 不论当前是否本来就关闭，都按需求弹窗提示一次
      showFirstLoadModal.value = true;
    }

    // 递增版本号，使 onModuleToggle 中正在进行的异步加载完成后不再更新状态
    moduleToggleVersion += 1;

    // 先取消左侧面板中正在加载的模块
    const loadingModuleNames = scenePanelRef.value?.getLoadingModules?.() || [];
    for (const loadingName of loadingModuleNames) {
      if (loadingName !== moduleName) {
        gsManager?.manualUnloadModule(loadingName);
        scenePanelRef.value?.onModuleUnloaded?.(loadingName);
      }
    }

    // 再卸载所有其他已加载的模块
    const allModules = (gsManager?.getModules() ?? []) as RegionModule[];
    for (const mod of allModules) {
      if (mod.name !== moduleName && gsManager?.isModuleLoaded(mod.name)) {
        gsManager.manualUnloadModule(mod.name);
        scenePanelRef.value?.onModuleUnloaded?.(mod.name);
      }
    }

    // 加载当前模块
    moduleLoading.value = true;
    try {
      await gsManager?.manualLoadModule(moduleName);
      currentModuleInfo.value = { ...currentModuleInfo.value, isLoaded: true };
      scenePanelRef.value?.onModuleLoaded(moduleName);
    } catch (error) {
      console.error(`加载模块 ${moduleName} 失败:`, error);
      scenePanelRef.value?.onModuleLoadFailed(moduleName);
    } finally {
      moduleLoading.value = false;
    }
  }
}

/**
 * 模块点击事件处理：手动加载/卸载高斯泼溅模块
 */
async function onModuleToggle(moduleName: string, shouldLoad: boolean) {
  // B8：旧 getGaussianSplattingManager() 删除，改走 ECS getModule 范式拿 gs3d handle
  // v20260813（thirdroom 路径 3）：下游消费改走 getCtx() inject，与 sdk 门面解耦
  const ctx = getCtx();
  const gsManager = ctx
    ? getModule<Gs3dModuleState>(ctx, gs3dModule).handle
    : null;
  if (shouldLoad) {
    // 记录当前版本号，用于加载完成后判断是否已被浮层操作取消
    const versionAtStart = moduleToggleVersion;
    try {
      await gsManager?.manualLoadModule(moduleName);
      // 如果版本号已变化，说明加载期间浮层触发了新的加载操作，当前结果应被忽略
      if (versionAtStart !== moduleToggleVersion) {
        console.log(`模块 ${moduleName} 的面板加载已被浮层操作取消，忽略回调`);
        return;
      }
      scenePanelRef.value?.onModuleLoaded(moduleName);
      // 同步更新当前所在模块信息浮层的加载状态
      if (currentModuleInfo.value?.moduleName === moduleName) {
        currentModuleInfo.value = { ...currentModuleInfo.value, isLoaded: true };
      }
    } catch (error) {
      // 如果版本号已变化，说明是被取消导致的错误，静默忽略
      if (versionAtStart !== moduleToggleVersion) {
        console.log(`模块 ${moduleName} 的面板加载已被浮层操作取消，忽略错误`);
        return;
      }
      console.error(`加载模块 ${moduleName} 失败:`, error);
      scenePanelRef.value?.onModuleLoadFailed(moduleName);
    }
  } else {
    gsManager?.manualUnloadModule(moduleName);
    // 同步更新当前所在模块信息浮层的加载状态
    if (currentModuleInfo.value?.moduleName === moduleName) {
      currentModuleInfo.value = { ...currentModuleInfo.value, isLoaded: false };
    }
  }
}
